 "Now I'm going to do a quick test in your nose, okay? Breathe slowly through your mouth. Try to relax for me. I'll gently put this thin swab into your nose. Keep your head still for me. It might tickle a little, but it'll be over soon. All done! You were so brave.": "./audio/cards/ca979480af9f58250e23.mp3",
 "Flu and COVID are going around now. So we'll do a quick test with a nose swab. She looks well overall, and she's breathing comfortably. But she still has a fever, and flu and COVID are going around. Let's do the tests to be safe. — Okay. What happens if it's positive? — If the flu test is positive, I'll prescribe medicine to treat the flu. I'll also give cold medicine for her symptoms, and fever medicine for the fever. Once the fever comes down, you don't need to worry. Please keep an eye on her at home until she's fully better. She can go back to daycare or school when she meets their return requirements. Please bring her back if the fever doesn't come down, she seems very weak, or she's having trouble breathing.": "./audio/cards/38fad7cd7c9737c5c03f.mp3",
 "Small children often wheeze as soon as they get a cold. She wheezes every time she catches a cold, doesn't she? It sounds like asthma. But in most cases, it is not true asthma. If she wheezes three or more times, and it gets better with a nebulizer treatment, we call it childhood asthma for now. But in most cases, it is temporary. Very few children get true asthma. Each time, we treat her cold and help calm her sensitive airways. If we clear the inflammation each time, most children grow out of it. Only a few children have true asthma. They need long-term treatment.": "./audio/cards/c564926f3132779cbf8e.mp3",
 "Good morning. May I see your passport, please? Thank you. What's the purpose of your visit? — I'm here on vacation with my family. — How long are you staying? — About a week. — Where are you staying? — At a hotel near Paddington. Here's the booking. — And what do you do for a living? — I'm a pediatrician. I run a children's clinic in Tokyo. — Do you have a return ticket? — Yes, here's my return flight. — Great. Enjoy your stay. — Thank you.": "./audio/cards/7b68537a9fcefab8f753.mp3",
 "Do you have anything to declare? — No, nothing to declare. — Are you carrying any food, plants, or meat? — Just some snacks — they're still sealed. — Could you open your bag, please? — Sure, go ahead. — What's this? — It's medicine for my child. I have the prescription. — That's fine. You can go ahead.": "./audio/cards/9d72674eaef209d75bf7.mp3",
 "Hi, welcome. Checking in? — Yes, it's under Komori. — Thank you. Could I see your passport and a credit card for incidentals? — Sure, here you go. Is breakfast included? — Yes, breakfast is served from seven to ten on the ground floor. You're in room 512, on the fifth floor. — What time is checkout? — Checkout is at eleven. — Could we get a late checkout? — Let me check... Twelve o'clock is fine. — Great, thank you.": "./audio/cards/ca9f8f1806d7dee1452b.mp3",
 "In First or Club World, please take care of your personal electronic device when adjusting your seat. If your device does get lost, please do not move the seat. Instead, please let a member of the crew know and we will be happy to assist you. Here at British Airways, our BA Better World Community Fund creates life-changing opportunities while supporting amazing projects and charities that align with our sustainability programme. Shortly, we will pause the in-flight entertainment to share a short video with you. If you would like to get involved, you can, right now, by simply donating any spare change in any currency into our charity collection bag, which a member of the crew will bring through the cabin soon. On behalf of all of our partners, we thank you in advance for your continued support and generosity.": "./audio/cards/ef7746cd6a2832ee26f8.mp3",
 "Japan recommends the use of the Visit Japan Web service for immigration and customs procedures. Please note that paper forms are no longer distributed on board the aircraft, so we kindly ask that you complete the necessary procedures online via the Visit Japan web page, or fill in the required forms upon arrival at Haneda Airport. In addition to this, the Asian Games are currently being held in Japan, so please note that the BA customer service team in Haneda has advised us that quarantine and customs inspections may be more stringent than usual during this period. Also, we will be switching the seat belt signs on in under 20 minutes, so the toilets will no longer be available after this point, because the cabin crew will need to come through and secure the cabin ready for landing. So if you do need to use the bathroom now, please make your way to the lavatory before we do switch on the seat belt signs. Thank you, and we hope you've had a good flight with us today.": "./audio/cards/aff23194a7d0fc220387.mp3",
 "Customers sitting in a front row seat or in an emergency exit row should place all items in the overhead lockers, leaving the floor area around your seat completely clear for landing. Please check that your table is folded away, your seat is in the landing position with the armrest down, your footrest has been stowed, and your seatbelt is securely fastened. If you are seated by a window and have lowered the blind, please return this to the open position for landing. Our Wi-Fi service will shortly be switched off; however, you may continue to use any handheld electronic devices for landing. Larger items, including laptops, must now be switched off and stowed away safely.": "./audio/cards/a3055406c4a577b62e1e.mp3",
 "Please remain seated with your seatbelt securely fastened until the fasten seatbelt signs have been switched off. And when it is safe to do so, please take care when opening the overhead lockers, as items may have moved and could fall out, causing injury. You can now make calls as well as use all data services on your handheld electronic devices. Before leaving the aircraft today, please check that you have all of your personal belongings with you, and do check your seat pocket and any other storages before leaving us. For those customers who pre-ordered special assistance to leave the aircraft today, do remain seated until the aisle around you is clear, and one of our crew will be on hand to assist you. On behalf of the cabin crew and British Airways, I'd like to thank you for choosing to fly with us today, and we do hope you have a great morning. Thank you.": "./audio/cards/57f59b07d62ffb6e8a97.mp3",
 "Welcome to Haneda Airport. We've just arrived here just over 15 minutes early, and very shortly we'll have you disembarking through the forward left-hand doors into Terminal 3. We do hope you've enjoyed your flight with us. As always, it's a pleasure flying you around the world. We do hope that you'll offer us the opportunity to welcome you on board British Airways again soon. Thank you very much, and have a very pleasant day.": "./audio/cards/62837447a4c11250e59a.mp3",
