 "As a child, I was good with my hands.": "./audio/cards/19b19146caa17991d20b.mp3",
 "I loved tinkering with machines and making things.": "./audio/cards/56473c3a9c79019d2401.mp3",
 "In medical school, I saw pediatric surgery as a way to help build a child's future.": "./audio/cards/79ca87cfa099f75528f4.mp3",
 "So I chose pediatric surgery.": "./audio/cards/679a1491d723d471710c.mp3",
 "We use surgery to save the lives of tiny babies.": "./audio/cards/36bc22ec81720beb303d.mp3",
 "But over the years, something started to bother me.": "./audio/cards/756f0cf5b92aa011fe66.mp3",
 "The diseases we operate on are the end of a long road.": "./audio/cards/e4a159b7cebe3c09163a.mp3",
 "I began to wonder if there was more we could do before children got to that point.": "./audio/cards/b16ef0d4574c6bbf7c1a.mp3",
 "As I worked with children in the community, I began to see things that way.": "./audio/cards/89b10e1862d6c2af9e9a.mp3",
 "The answer was nutrition.": "./audio/cards/4ca7b31e140d42ae82a5.mp3",
 "The food we eat provides what our bodies need to build cells and make energy.": "./audio/cards/4845ffb8fc1255bc9e02.mp3",
 "Nutrition is linked to how well we recover, how often we catch colds, and our mental health.": "./audio/cards/83bceebcb731da9afa17.mp3",
 "Looking at nutrition helped me understand many children who weren't ill but still didn't feel well.": "./audio/cards/985d392c52d0db337791.mp3",
