 "I'm hooked.": "./audio/cards/cc8984efdc0186f1d0c6.mp3",
 "And I can see it working in my clinic.": "./audio/cards/d3f079665970cced9062.mp3",
 "I'd like to share this approach with people across Japan.": "./audio/cards/c5d3471586b7bbcff8b8.mp3",
 "What matters most to me is what is real, true, and genuine.": "./audio/cards/ce37f3f57661dfe30930.mp3",
 "I try to live by my principles and remember to be grateful.": "./audio/cards/9bf3978b06691924c510.mp3",
 "I believe in helping each other and sharing what we have.": "./audio/cards/9042efa852a8bd28e608.mp3",
